<template>
  <div class="rating-section">
    <p class="current-rating">{{ label }}: {{ displayRating }}</p>
    <div v-if="editable" class="stars-input">
      <!-- Loop through 5 star positions -->
      <div v-for="starPosition in 5" :key="'star-' + starPosition" class="star-container">
        <!-- Left half of the star -->
        <span
          class="star-half left-half"
          @click="setRating(starPosition - 0.5)"
          @mouseover="hoverRating = starPosition - 0.5"
          @mouseleave="hoverRating = 0"
          :class="{ 
            'filled': (currentVisualRating >= starPosition - 0.5),
            'hovered': (hoverRating >= starPosition - 0.5) && (hoverRating < starPosition)
          }"
        >★</span>
        <!-- Right half of the star -->
        <span
          class="star-half right-half"
          @click="setRating(starPosition)"
          @mouseover="hoverRating = starPosition"
          @mouseleave="hoverRating = 0"
          :class="{
            'filled': (currentVisualRating >= starPosition),
            'hovered': (hoverRating >= starPosition)
          }"
        >★</span>
      </div>
    </div>
    <div v-else class="stars-display">
      <div v-for="starPosition in 5" :key="'display-star-' + starPosition" class="star-container">
        <span
          class="star-display"
          :class="{ 
            'filled': rating >= starPosition,
            'half-filled': rating >= starPosition - 0.5 && rating < starPosition
          }"
        >★</span>
      </div>
    </div>
  </div>
</template>

<script setup>
import { ref, computed, defineProps, defineEmits, watch } from 'vue';

// Props
const props = defineProps({
  rating: {
    type: Number,
    default: null,
    validator: (value) => value === null || (value >= 0 && value <= 5)
  },
  editable: {
    type: Boolean,
    default: true
  },
  label: {
    type: String,
    default: 'Rating'
  },
  size: {
    type: String,
    default: 'medium',
    validator: (value) => ['small', 'medium', 'large'].includes(value)
  }
});

// Emits
const emit = defineEmits(['update:rating', 'rating-changed']);

// Reactive data
const hoverRating = ref(0);
const currentRating = ref(props.rating);

// Computed
const displayRating = computed(() => {
  return (currentRating.value !== null && currentRating.value !== undefined) 
    ? `${currentRating.value}/5` 
    : 'Not Rated';
});

const currentVisualRating = computed(() => {
  return hoverRating.value > 0 ? hoverRating.value : (currentRating.value || 0);
});

// Methods
const setRating = (rating) => {
  if (!props.editable) return;
  
  currentRating.value = rating;
  emit('update:rating', rating);
  emit('rating-changed', rating);
};

// Watch for external changes
watch(() => props.rating, (newValue) => {
  currentRating.value = newValue;
});
</script>

<style scoped>
.rating-section {
  margin: 15px 0;
}

.current-rating {
  margin: 0 0 8px 0;
  font-weight: 500;
  color: #e0e0e0;
}

.stars-input,
.stars-display {
  display: flex;
  align-items: center;
  gap: 2px;
}

.star-container {
  position: relative;
  display: inline-block;
}

/* Editable stars */
.star-half {
  font-size: var(--star-size, 1.5rem);
  color: #444;
  cursor: pointer;
  transition: all 0.2s ease;
  position: absolute;
  top: 0;
  width: 50%;
  overflow: hidden;
  user-select: none;
}

.star-half.left-half {
  left: 0;
  text-align: left;
}

.star-half.right-half {
  right: 0;
  text-align: right;
}

.star-half.filled {
  color: #ffd700;
  text-shadow: 0 0 3px rgba(255, 215, 0, 0.3);
}

.star-half.hovered {
  color: #ffed4e;
  transform: scale(1.1);
}

/* Display-only stars */
.star-display {
  font-size: var(--star-size, 1.5rem);
  color: #444;
  transition: all 0.2s ease;
  user-select: none;
}

.star-display.filled {
  color: #ffd700;
  text-shadow: 0 0 3px rgba(255, 215, 0, 0.3);
}

.star-display.half-filled {
  background: linear-gradient(90deg, #ffd700 50%, #444 50%);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
}

/* Size variations */
:root {
  --star-size: 1.5rem;
}

.rating-section.small {
  --star-size: 1rem;
}

.rating-section.large {
  --star-size: 2rem;
}

/* Ensure proper spacing for star containers */
.star-container {
  width: calc(var(--star-size, 1.5rem) + 2px);
  height: var(--star-size, 1.5rem);
  margin-right: 2px;
}

.star-container:last-child {
  margin-right: 0;
}
</style>
